## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/tkaLogic.ts`

```typescript
export type AffectedSide = "right" | "left" | "bilateral";
export type KLGrade = "0" | "1" | "2" | "3" | "4";

export type TKAInput = {
  age: string; bmi: string; affectedSide: AffectedSide | ""; painScore: string; klGrade: KLGrade | "";
  koosPainScore: string; koosADLScore: string;
  kellgrenLawrence: string; symptomDurationMonths: string;
  conservativeTherapyMonths: string; conservativeTherapies: string[];
  comorbidities: string[]; functionalLimitations: string[];
  activeInfection: boolean; activeKneeInfection: boolean;
  severeVascularDisease: boolean; extensorMechanismDeficiency: boolean;
  priorKneeInfection: boolean; medicallyUnfit: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessTKA(input: TKAInput) {
  const age = parseFloat(input.age) || 0;
  const bmi = parseFloat(input.bmi) || 0;
  const koosPain = parseFloat(input.koosPainScore) || 100;
  const koosADL = parseFloat(input.koosADLScore) || 100;
  const kl = parseInt(input.klGrade || input.kellgrenLawrence) || 0;
  const painScore = parseFloat(input.painScore) || 0;
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active systemic infection — absolute contraindication");
  if (input.activeKneeInfection) contraindications.push("Active knee joint infection — absolute contraindication");
  if (input.severeVascularDisease) contraindications.push("Severe peripheral vascular disease — high surgical risk");
  if (input.medicallyUnfit) contraindications.push("Medically unfit for surgery — requires optimization");

  if (contraindications.length > 0) {
    return { recommendation: "TKA Contraindicated or Requires Optimization", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["One or more absolute or relative contraindications identified. Address before proceeding."], contraindications, optimizationSteps: ["Obtain infectious disease clearance if infection present", "Vascular surgery consultation for PVD", "Medical optimization for surgical fitness"] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  if (kl >= 3 && koosPain <= 45 && koosADL <= 45 && conservMonths >= 3) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Radiographic evidence of moderate-severe OA (KL ≥3) with significant functional impairment");
    rationale.push("KOOS pain and ADL scores indicate substantial disability");
    rationale.push("Conservative therapy trial completed");
    rationale.push("TKA is strongly recommended per AAOS guidelines");
  } else if (kl >= 2 && koosPain <= 55 && conservMonths >= 3) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Moderate OA with meaningful pain and functional limitation");
    rationale.push("Adequate conservative therapy trial documented");
    rationale.push("TKA is a reasonable option per shared decision-making");
  } else if (kl >= 2 && conservMonths < 3) {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("OA severity supports eventual TKA but conservative therapy trial is insufficient");
    optimizationSteps.push("Continue physical therapy, weight management, and analgesics for ≥3 months");
    optimizationSteps.push("Consider intraarticular corticosteroid or hyaluronic acid injection");
  } else {
    cor = "IIb"; urgency = "Insufficient Criteria";
    rationale.push("Radiographic or functional criteria for TKA not yet met");
    optimizationSteps.push("Repeat weight-bearing X-rays with KL grading");
    optimizationSteps.push("Complete KOOS functional assessment");
    optimizationSteps.push("Ensure adequate conservative therapy trial (≥3 months)");
  }

  if (bmi > 40) optimizationSteps.push("BMI >40: weight loss to <40 recommended before elective TKA to reduce complication risk");
  if (age < 55) optimizationSteps.push("Age <55: discuss implant longevity and potential need for revision surgery");
  if (input.comorbidities.includes("diabetes")) optimizationSteps.push("Optimize glycemic control (HbA1c <8%) before surgery");
  if (input.comorbidities.includes("smoking")) optimizationSteps.push("Smoking cessation ≥4 weeks before surgery");

  return { recommendation: cor === "I" ? "TKA Recommended" : cor === "IIa" ? "TKA Reasonable" : "TKA — Additional Criteria Needed", cor, loe: kl >= 3 ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
